SET NAMES utf8mb4;
SET foreign_key_checks = 0;

-- --------------------------------------------------------
-- Lentelės struktūra: `dalyviai`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `dalyviai`;
CREATE TABLE `dalyviai` (
  `reg_id` int(11) NOT NULL AUTO_INCREMENT,
  `konkurso_pav` varchar(255) NOT NULL,
  `var_mokykla` varchar(100) NOT NULL,
  `pil_data` datetime NOT NULL,
  `1_vardas` varchar(30) NOT NULL,
  `1_pavarde` varchar(30) NOT NULL,
  `1_klase` varchar(10) NOT NULL,
  `1_mok` varchar(50) NOT NULL,
  `1_mok_kvali` varchar(30) NOT NULL,
  `2_mok` varchar(100) NOT NULL,
  `2_mok_kvali` varchar(100) NOT NULL,
  `vart_id` varchar(20) NOT NULL,
  `inf_1` text DEFAULT NULL,
  `inf_2` text DEFAULT NULL,
  `Balai` varchar(10) DEFAULT NULL,
  `Vieta` varchar(10) DEFAULT NULL,
  `status` tinyint(1) DEFAULT 1,
  `kodas` varchar(10) DEFAULT NULL,
  `pastabos` text DEFAULT NULL,
  `vertintojas` varchar(50) DEFAULT NULL,
  `kitas_etapas` int(11) NOT NULL DEFAULT 0 COMMENT 'ar dalyvis siunčiamas į kitą etapą',
  PRIMARY KEY (`reg_id`),
  UNIQUE KEY `uniq_dalyvis_olimpiadoje` (`1_vardas`,`1_pavarde`,`var_mokykla`,`konkurso_pav`),
  KEY `idx_var_mokykla` (`var_mokykla`),
  KEY `idx_konkurso_pav` (`konkurso_pav`)
) ENGINE=InnoDB AUTO_INCREMENT=2053 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Duomenys lentelėje `dalyviai`

-- --------------------------------------------------------
-- Lentelės struktūra: `konkursai`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `konkursai`;
CREATE TABLE `konkursai` (
  `konk_id` int(11) NOT NULL AUTO_INCREMENT,
  `konkurso_pav` varchar(255) NOT NULL,
  `atsakingas` varchar(100) NOT NULL,
  `status` tinyint(1) NOT NULL DEFAULT 0,
  `grupe` varchar(50) NOT NULL,
  `ne_rajono` tinyint(1) DEFAULT 0,
  `smsm_patvirtintas` tinyint(1) DEFAULT 0,
  `data` date DEFAULT NULL,
  `vieta` varchar(100) DEFAULT NULL,
  `aprasymas` text DEFAULT NULL,
  `sukurimo_data` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`konk_id`),
  UNIQUE KEY `uniq_konkurso_pav` (`konkurso_pav`)
) ENGINE=InnoDB AUTO_INCREMENT=65 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Duomenys lentelėje `konkursai`

-- --------------------------------------------------------
-- Lentelės struktūra: `system_logs`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `system_logs`;
CREATE TABLE `system_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` varchar(50) DEFAULT NULL,
  `action` varchar(255) NOT NULL,
  `details` text DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=46 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Duomenys lentelėje `system_logs`

-- --------------------------------------------------------
-- Lentelės struktūra: `teacher_activity_log`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `teacher_activity_log`;
CREATE TABLE `teacher_activity_log` (
  `log_id` int(11) NOT NULL AUTO_INCREMENT,
  `vart_id` varchar(50) NOT NULL,
  `var_mokykla` varchar(255) DEFAULT NULL,
  `action` varchar(150) NOT NULL,
  `details` text DEFAULT NULL,
  `reg_id` int(11) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`log_id`),
  KEY `idx_vart_id` (`vart_id`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

